from collections import defaultdict

class DisjointRangeUnion:

	def __init__(self):
		self.ranges = list()

	def add(self, begin, end):
		new_ranges = list()
		for (b, e) in self.ranges:
			if begin <= e and b <= end:
				begin = min(b, begin)
				end = max(e, end)
			else:
				new_ranges.append((b, e))
		new_ranges.append((begin, end))
		self.ranges = new_ranges

	def count(self):
		return sum((e - b for (b, e) in self.ranges))

	def __repr__(self):
		return repr(self.ranges)

def test_dru():
	dru = DisjointRangeUnion()
	dru.add(0, 5)
