def get_after_slow(k, T=0):
	dp = [k + 1 for _ in range(49 * k + 1)]
	dp[0] = 0
	for i in range(1, 49 * k + 1):
		for R in R1:
			if i >= R:
				dp[i] = min(dp[i], dp[i - R] + 1)
	return len(dp) - T - dp[T:].count(k + 1)

def get_fast(k):
